# Source endpoint wraps the frozen gzip/tar archive as base64. A trailing newline/padding
# byte may be trimmed by the API response adapter, so decode only for inspection and
# compare content-level hashes against the baseline manifest rather than claiming the
# byte-level archive digest from this reconstruction.
blob=base64.b64decode("".join(parts))
print("reconstructed_archive_bytes",len(blob),"decoded_prefix",blob[:8].hex())
with tarfile.open(fileobj=io.BytesIO(blob), mode="r:gz") as tf:
    files={m.name.rsplit("/",1)[-1]:m for m in tf.getmembers() if m.isfile()}
    print("archive_members",len(files))
    for name in ("Abaddon_the_Despoiler.csv","Abaddon_the_Despoiler.txt"):
        raw=tf.extractfile(files[name]).read()
        print("FILE",name,"bytes",len(raw),"sha256",hashlib.sha256(raw).hexdigest())
        print(raw.decode("utf-8-sig")[:2200])
